<?php
declare(strict_types=1);requireRole('social-service-officer');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';require_once __DIR__.'/../../includes/eligibility.php';$activePage='distribute-aid';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);$db=database();$userId=(int)$_SESSION['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){$type=(string)($_POST['distribution_type']??'');$beneficiaryId=filter_input(INPUT_POST,'beneficiary_id',FILTER_VALIDATE_INT);$itemId=filter_input(INPUT_POST,'item_id',FILTER_VALIDATE_INT);$requestId=filter_input(INPUT_POST,'aid_request_id',FILTER_VALIDATE_INT);$quantity=filter_input(INPUT_POST,'quantity',FILTER_VALIDATE_INT);$notes=trim((string)($_POST['notes']??''));if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!in_array($type,['direct','request-based'],true)||!$quantity||$quantity<1)$errors[]='Invalid distribution details.';if(mb_strlen($notes)>1000)$errors[]='Notes cannot exceed 1000 characters.';if(!$errors){try{$db->beginTransaction();if($type==='request-based'){$request=$db->prepare("SELECT ar.* FROM aid_requests ar JOIN beneficiaries b ON b.id=ar.beneficiary_id WHERE ar.id=:id AND ar.status='approved' AND b.ds_division_id=(SELECT ds_division_id FROM users WHERE id=:user) FOR UPDATE");$request->execute(['id'=>$requestId,'user'=>$userId]);$request=$request->fetch();if(!$request)throw new RuntimeException('Approved request is unavailable or outside your division.');$beneficiaryId=(int)$request['beneficiary_id'];$itemId=(int)$request['item_id'];if($quantity!==(int)$request['quantity'])throw new RuntimeException('Distribution quantity must match the approved request.');}elseif(!$beneficiaryId||!$itemId)throw new RuntimeException('Select a beneficiary and item.');$scope=$db->prepare("SELECT id FROM beneficiaries WHERE id=:id AND status='active' AND ds_division_id=(SELECT ds_division_id FROM users WHERE id=:user)");$scope->execute(['id'=>$beneficiaryId,'user'=>$userId]);if(!$scope->fetchColumn())throw new RuntimeException('Beneficiary is outside your assigned division or inactive.');$eligibility=beneficiaryEligibility($db,(int)$beneficiaryId,(int)$itemId);if(!$eligibility['eligible'])throw new RuntimeException($eligibility['reason']);if($eligibility['item']['distribution_type']!==$type)throw new RuntimeException('The item distribution type does not match this workflow.');$pool=$db->prepare('SELECT allocated,distributed,reused FROM officer_pools WHERE officer_id=:officer AND item_id=:item FOR UPDATE');$pool->execute(['officer'=>$userId,'item'=>$itemId]);$balance=$pool->fetch();$available=$balance?(int)$balance['allocated']-(int)$balance['distributed']+(int)$balance['reused']:0;if($available<$quantity)throw new RuntimeException("Insufficient pool quota. Available: $available.");$db->prepare('UPDATE officer_pools SET distributed=distributed+:quantity WHERE officer_id=:officer AND item_id=:item')->execute(['quantity'=>$quantity,'officer'=>$userId,'item'=>$itemId]);$insert=$db->prepare('INSERT INTO distributions(aid_request_id,beneficiary_id,item_id,quantity,distribution_type,notes,distributed_by) VALUES(:request,:beneficiary,:item,:quantity,:type,:notes,:officer)');$insert->execute(['request'=>$type==='request-based'?$requestId:null,'beneficiary'=>$beneficiaryId,'item'=>$itemId,'quantity'=>$quantity,'type'=>$type,'notes'=>$notes?:null,'officer'=>$userId]);$distributionId=(int)$db->lastInsertId();if($type==='request-based')$db->prepare("UPDATE aid_requests SET status='distributed' WHERE id=:id")->execute(['id'=>$requestId]);$db->commit();logActivity('Distribution','Issued aid from officer pool','DIST-'.str_pad((string)$distributionId,4,'0',STR_PAD_LEFT),$type);$_SESSION['flash_success']='Distribution recorded and pool quota updated.';unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=distribute-aid');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to complete distribution.';}}}
try{$beneficiaries=$db->prepare("SELECT id,full_name,nic FROM beneficiaries WHERE status='active' AND ds_division_id=(SELECT ds_division_id FROM users WHERE id=:user) ORDER BY full_name");$beneficiaries->execute(['user'=>$userId]);$beneficiaries=$beneficiaries->fetchAll();$poolItems=$db->prepare("SELECT p.item_id,i.item_name,i.variety,c.distribution_type,(p.allocated-p.distributed+p.reused) available FROM officer_pools p JOIN inventory_items i ON i.id=p.item_id JOIN item_categories c ON c.id=i.category_id WHERE p.officer_id=:user AND (p.allocated-p.distributed+p.reused)>0 ORDER BY i.item_name");$poolItems->execute(['user'=>$userId]);$poolItems=$poolItems->fetchAll();$approved=$db->prepare("SELECT ar.id,ar.quantity,b.full_name,b.nic,i.item_name,i.variety FROM aid_requests ar JOIN beneficiaries b ON b.id=ar.beneficiary_id JOIN inventory_items i ON i.id=ar.item_id WHERE ar.status='approved' AND b.ds_division_id=(SELECT ds_division_id FROM users WHERE id=:user) ORDER BY ar.reviewed_at");$approved->execute(['user'=>$userId]);$approved=$approved->fetchAll();$today=$db->prepare('SELECT d.*,b.full_name,i.item_name,i.variety FROM distributions d JOIN beneficiaries b ON b.id=d.beneficiary_id JOIN inventory_items i ON i.id=d.item_id WHERE d.distributed_by=:user AND DATE(d.distributed_at)=CURDATE() ORDER BY d.id DESC');$today->execute(['user'=>$userId]);$today=$today->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$beneficiaries=$poolItems=$approved=$today=[];$errors[]='Distribution workflow is unavailable.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Distribute Items | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body class="distribution-page-body"><?php require __DIR__.'/../../includes/social-service-officer-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Distribute Items</h1></div></header><main class="dashboard-content distribution-page"><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif;?><div class="distribution-tabs"><button class="distribution-tab active" data-distribution-tab="direct-panel">Direct Distribution</button><button class="distribution-tab" data-distribution-tab="request-panel">Request-Based Distribution</button></div>
<section class="distribution-panel active" id="direct-panel"><article class="distribution-card"><div class="distribution-card-header"><h2>Direct Distribution</h2><small>No prior request needed</small></div><form method="post" class="distribution-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="distribution_type" value="direct"><div class="distribution-notice success"><strong>Eligible direct items</strong><span>Eligibility and pool stock are checked when issued.</span></div><div class="distribution-grid two-columns"><label>Beneficiary *<select name="beneficiary_id" required><option value="">Select beneficiary</option><?php foreach($beneficiaries as $b):?><option value="<?=(int)$b['id']?>"><?=htmlspecialchars($b['full_name'].' — '.$b['nic'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>Item *<select name="item_id" required><option value="">Select direct item</option><?php foreach($poolItems as $i):?><?php if($i['distribution_type']==='direct'):?><option value="<?=(int)$i['item_id']?>"><?=htmlspecialchars($i['item_name'].($i['variety']?' — '.$i['variety']:'').' ('.$i['available'].' available)',ENT_QUOTES,'UTF-8')?></option><?php endif;?><?php endforeach;?></select></label></div><div class="distribution-grid two-columns"><label>Quantity *<input type="number" name="quantity" value="1" min="1" required></label><label>Notes<textarea name="notes" rows="2" maxlength="1000"></textarea></label></div><div class="distribution-actions"><button class="distribution-primary-button">Issue Item Directly</button></div></form></article></section>
<section class="distribution-panel" id="request-panel" hidden><article class="distribution-card"><div class="distribution-card-header"><h2>Request-Based Distribution</h2><small>Approved requests only</small></div><form method="post" class="distribution-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="distribution_type" value="request-based"><div class="distribution-notice warning"><strong>Prior approval required</strong><span>The approved request supplies the beneficiary and item.</span></div><div class="distribution-grid two-columns"><label>Approved Request *<select name="aid_request_id" required><option value="">Select approved request</option><?php foreach($approved as $r):?><option value="<?=(int)$r['id']?>">AR-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?> — <?=htmlspecialchars($r['full_name'].' — '.$r['item_name'].' × '.$r['quantity'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>Approved Quantity *<input type="number" name="quantity" min="1" value="1" required></label></div><label class="distribution-full-field">Notes<textarea name="notes" rows="2" maxlength="1000"></textarea></label><div class="distribution-actions"><button class="distribution-primary-button">Confirm Distribution</button></div></form></article></section>
<section class="distribution-history-card"><div class="distribution-history-header"><h2>Today's Distributions</h2></div><div class="distribution-table-wrap"><table class="distribution-table"><thead><tr><th>Beneficiary</th><th>Item</th><th>Type</th><th>Qty</th><th>Source</th><th>Time</th><th>Ref</th></tr></thead><tbody><?php if(!$today):?><tr><td colspan="7" class="distribution-empty">No distributions recorded today.</td></tr><?php else:foreach($today as $r):?><tr><td><?=htmlspecialchars($r['full_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['item_name'].($r['variety']?' — '.$r['variety']:''),ENT_QUOTES,'UTF-8')?></td><td><?=ucwords(str_replace('-',' ',$r['distribution_type']))?></td><td><?=(int)$r['quantity']?></td><td>My Pool Quota</td><td><?=date('h:i A',strtotime($r['distributed_at']))?></td><td>DIST-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script><script>document.querySelectorAll('[data-distribution-tab]').forEach(t=>t.addEventListener('click',()=>{document.querySelectorAll('[data-distribution-tab]').forEach(x=>x.classList.toggle('active',x===t));document.querySelectorAll('.distribution-panel').forEach(p=>p.hidden=p.id!==t.dataset.distributionTab)}));</script></body></html>
